<?php require_once __DIR__ . '/icons.php'; $isHistory=!empty($deliverySearch['history']); $listPage=$isHistory?'history':'deliveries'; $pendingOnly=!empty($deliverySearch['pendingOnly']); $filter=$isHistory ? '' : '&amp;f=' . ($pendingOnly ? 'pending' : 'all');
// Plazo de respuesta informado al paciente (24 h por defecto) contado desde la creación de la solicitud.
$slaHours=(int)$app->config['whatsapp_estimated_hours'];
$sla=function(array $row) use ($slaHours): array { $left=strtotime($row['created_at'])+$slaHours*3600-time(); $h=intdiv(abs($left),3600); $m=intdiv(abs($left)%3600,60);
  if ($left<0) return ['late','Vencida','hace '.($h?$h.' h ':'').$m.' min']; return [$left<6*3600?'soon':'ok',$left<6*3600?'Por vencer':'A tiempo','quedan '.($h?$h.' h ':'').$m.' min']; }; ?>
<section class="card" id="deliveries"><h2 class="visually-hidden"><?= $isHistory ? 'Historial de historias enviadas' : 'Solicitudes' ?></h2><?php if ($isHistory): ?><p class="muted">Los casos reabiertos pasan a Solicitudes hasta completar un nuevo envío.</p><?php elseif ($pendingOnly): ?><p class="muted"><?= 'Solicitudes sin historia enviada, de la más antigua a la más reciente. El paciente recibió un tiempo estimado de respuesta de ' . $slaHours . ' horas. Abre cada una para responder «Aprobado» (con los documentos) o «No Registra».' ?></p><?php endif ?>
<?php if (!$isHistory): ?><nav class="segmented" aria-label="Filtro de solicitudes"><a href="?page=deliveries&amp;f=pending&amp;q=<?= rawurlencode($deliverySearch['query']) ?>" <?= $pendingOnly ? 'aria-current="page"' : '' ?>>Pendientes<?php if (!empty($pendingCount)): ?> (<?= (int)$pendingCount ?>)<?php endif ?></a><a href="?page=deliveries&amp;f=all&amp;q=<?= rawurlencode($deliverySearch['query']) ?>" <?= !$pendingOnly ? 'aria-current="page"' : '' ?>>Todas</a></nav><?php endif ?>
<?php if (!$isHistory && $pendingOnly && $deliverySearch['query'] === ''): $oldest = $deliverySearch['rows'][0] ?? null; ?><div class="queue-board<?= $oldest ? ' has-waiting' : '' ?>"><p class="call-number"><strong class="call-ref"><?= (int)$deliverySearch['total'] ?></strong><span class="call-label"><?= (int)$deliverySearch['total'] === 1 ? 'solicitud en espera' : 'solicitudes en espera' ?></span></p><?php if ($oldest): ?><a class="button primary" data-delivery-modal aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$oldest['id'] ?>">Atender la más antigua <?= ui_icon('arrow-right', 18) ?></a><?php endif ?></div><?php endif ?><form method="get" class="delivery-search"><input type="hidden" name="page" value="<?= $listPage ?>"><?php if (!$isHistory): ?><input type="hidden" name="f" value="<?= $pendingOnly ? 'pending' : 'all' ?>"><?php endif ?><label for="delivery-query">Nombre, radicado o número de documento<input id="delivery-query" type="search" name="q" maxlength="160" placeholder="Ej.: nombre completo, HC-… o cédula" value="<?= h($deliverySearch['query']) ?>"></label><button class="button primary" type="submit"><?= ui_icon('search', 18) ?>Buscar</button><?php if ($deliverySearch['query'] !== ''): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>">Limpiar</a><?php endif ?></form>
<p class="result-count" role="status"><strong class="mono"><?= (int)$deliverySearch['total'] ?></strong> solicitud(es)<?= $deliverySearch['query'] !== '' ? ' para «' . h($deliverySearch['query']) . '»' : '' ?>.</p>
<?php if (!$deliverySearch['rows']): ?><div class="empty-state"><?= ui_icon($pendingOnly && $deliverySearch['query'] === '' ? 'check-circle' : 'search', 28) ?><p><?= $pendingOnly && $deliverySearch['query'] === '' ? 'No hay solicitudes pendientes. Todas tienen historia enviada o una respuesta.' : ($isHistory ? 'No hay historias enviadas que coincidan con la búsqueda. Las entregas simuladas o fallidas no aparecen en este historial.' : 'No se encontraron solicitudes con esos datos. Prueba con parte del nombre, el radicado o el documento.') ?></p></div>
<?php else: ?>
<?php if ($isHistory): require __DIR__ . '/delivery-history-rows.php'; else: ?><div class="table-wrap"><table class="responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Paciente</th><th scope="col" role="columnheader">Radicado / fecha</th><th scope="col" role="columnheader">Correo de entrega</th><?php if ($pendingOnly): ?><th scope="col" role="columnheader">Plazo</th><?php endif ?><th scope="col" role="columnheader">Estado</th><th scope="col" role="columnheader">Envíos</th><th scope="col" role="columnheader">Ver</th></tr></thead><tbody role="rowgroup">
<?php foreach ($deliverySearch['rows'] as $row): ?><tr role="row"><td role="cell" data-label="Paciente"><strong><?= h($row['claimed_name']) ?></strong><small><?= $row['document_number'] ? h($row['document_type'].' '.$row['document_number']) : 'Documento no conservado en esta solicitud antigua' ?></small></td><td role="cell" data-label="Radicado / fecha"><strong class="mono ref"><?= h($row['reference']) ?></strong><small class="mono"><?= h(date('d/m/Y H:i', strtotime($row['created_at']))) ?></small></td><td role="cell" data-label="Correo de entrega" class="delivery-email"><?= h($row['contact_email'] ?? '—') ?></td><?php if ($pendingOnly): [$slaClass,$slaLabel,$slaText]=$sla($row); ?><td role="cell" data-label="Plazo"><span class="pill sla-<?= $slaClass ?>"><?= ui_icon($slaClass === 'late' ? 'alert' : 'clock', 14) ?><?= $slaLabel ?></span><small><?= h($slaText) ?></small></td><?php endif ?><td role="cell" data-label="Estado"><?php if (!empty($row['whatsapp_phone'])): ?><span class="pill channel"><?= ui_icon('chat', 14) ?>WhatsApp</span><?php endif ?><?php if ($row['case_pending']): ?><span class="pill case-pending">Pendiente de gestión</span><small>Reabierto <?= h($row['case_reopened_at']) ?></small><?php endif ?><span class="pill <?= ui_tone($row['status']) ?>"><?= h($labels[$row['status']] ?? $row['status']) ?></span><?php if ($row['last_error']): ?><small class="danger with-icon"><?= ui_icon('alert', 14) ?>Último envío con error</small><?php endif ?></td><td role="cell" data-label="Envíos" class="num"><?= (int)$row['deliveries'] ?></td><td role="cell" data-label="Ver"><div class="row-actions"><a class="history-button small" data-history-modal aria-haspopup="dialog" href="?page=case-history&amp;id=<?= (int)$row['id'] ?>" aria-label="Historial del caso <?= h($row['reference']) ?>" title="Historial del caso"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg></a><a class="button secondary eye-button" data-delivery-modal aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$row['id'] ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= (int)$deliverySearch['page'] ?>" aria-label="Ver envío de <?= h($row['reference']) ?>" title="Ver detalle del envío"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></a></div></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
<nav class="delivery-pagination" aria-label="Páginas de solicitudes"><?php if ($deliverySearch['page']>1): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= $deliverySearch['page']-1 ?>"><?= ui_icon('arrow-left', 18) ?>Anterior</a><?php endif ?><span class="page-indicator">Página <strong class="mono"><?= (int)$deliverySearch['page'] ?></strong> de <span class="mono"><?= (int)$deliverySearch['pages'] ?></span></span><?php if ($deliverySearch['page']<$deliverySearch['pages']): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= $deliverySearch['page']+1 ?>">Siguiente<?= ui_icon('arrow-right', 18) ?></a><?php endif ?></nav>
<?php endif ?></section>
<?php require __DIR__ . '/detail-modals.php'; ?>
<?php if ($isHistory): ?>
<noscript><p class="muted">Sin JavaScript, «Reabrir» se aplica sin confirmación previa.</p></noscript>
<?php endif ?>
